import{_ as e,o as r,c as a,a2 as l}from"./chunks/framework.BeNN5tyQ.js";const f=JSON.parse(`{"title":"Підготовка до Інтерв'ю","description":"","frontmatter":{},"headers":[],"relativePath":"browser/async-defer.md","filePath":"browser/async-defer.md"}`),o={name:"browser/async-defer.md"};function s(d,t,n,c,i,g){return r(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="підготовка-до-інтерв-ю" tabindex="-1"><strong>Підготовка до Інтерв&#39;ю</strong> <a class="header-anchor" href="#підготовка-до-інтерв-ю" aria-label="Permalink to &quot;**Підготовка до Інтерв&#39;ю**&quot;">​</a></h1><div><h2 id="js-async-vs-defer" tabindex="-1"><strong>JS Async vs Defer</strong> <a class="header-anchor" href="#js-async-vs-defer" aria-label="Permalink to &quot;**JS Async vs Defer**&quot;">​</a></h2><p>Атрибути async та defer використовуються в тегу <code>&lt;script&gt;</code>, щоб оптимізувати завантаження сторінки. Вони дозволяють браузеру завантажувати JavaScript у фоновому режимі, не блокуючи відображення (рендеринг) HTML.</p><h3 id="_1-звичаинии-script-без-атрибутів" tabindex="-1"><strong>1. Звичайний &lt;script&gt; (без атрибутів)</strong> <a class="header-anchor" href="#_1-звичаинии-script-без-атрибутів" aria-label="Permalink to &quot;**1\\. Звичайний \\&lt;script\\&gt; (без атрибутів)**&quot;">​</a></h3><p>Браузер зупиняє обробку HTML, щойно зустрічає тег <code>&lt;script&gt;</code>. Він чекає, поки скрипт завантажиться з сервера, потім виконує його, і лише після цього продовжує малювати сторінку. Це призводить до довгого завантаження (білий екран).</p><h3 id="_2-script-async-асинхроннии" tabindex="-1"><strong>2. &lt;script async&gt; (Асинхронний)</strong> <a class="header-anchor" href="#_2-script-async-асинхроннии" aria-label="Permalink to &quot;**2\\. \\&lt;script async\\&gt; (Асинхронний)**&quot;">​</a></h3><p>Скрипт завантажується паралельно з HTML. Щойно скрипт повністю завантажений, браузер зупиняє парсинг HTML, виконує цей скрипт, а потім продовжує роботу з HTML.</p><blockquote><ul><li><strong>Порядок не гарантується:</strong> Якщо у вас є кілька async скриптів, вони виконаються в тому порядку, в якому встигли завантажитися (хто перший — той і виконався).</li><li><strong>Коли використовувати:</strong> Для повністю незалежних скриптів, яким не потрібен готовий DOM і які не залежать від інших скриптів (наприклад, Google Analytics, віджети реклами, лічильники).</li></ul></blockquote><h3 id="_3-script-defer-відкладении" tabindex="-1"><strong>3. &lt;script defer&gt; (Відкладений)</strong> <a class="header-anchor" href="#_3-script-defer-відкладении" aria-label="Permalink to &quot;**3\\. \\&lt;script defer\\&gt; (Відкладений)**&quot;">​</a></h3><p>Скрипт також завантажується паралельно з HTML, але його виконання відкладається до моменту, коли весь HTML буде повністю розібраний браузером (перед подією <code>DOMContentLoaded</code>).</p><blockquote><ul><li><strong>Порядок гарантується:</strong> Скрипти з defer завжди виконуються в тому порядку, в якому вони розташовані в коді HTML.</li><li><strong>Коли використовувати:</strong> Для більшості ваших скриптів. Особливо, якщо скрипт взаємодіє з елементами сторінки (DOM) або залежить від іншого скрипта (наприклад, спочатку завантажується бібліотека, а потім код, який її використовує).</li></ul></blockquote><h3 id="швидке-порівняння" tabindex="-1"><strong>Швидке порівняння</strong> <a class="header-anchor" href="#швидке-порівняння" aria-label="Permalink to &quot;**Швидке порівняння**&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Характеристика</th><th style="text-align:left;">Звичайний &lt;script&gt;</th><th style="text-align:left;">&lt;script async&gt;</th><th style="text-align:left;">&lt;script defer&gt;</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Завантаження</strong></td><td style="text-align:left;">Блокує HTML</td><td style="text-align:left;">Фонове (паралельне)</td><td style="text-align:left;">Фонове (паралельне)</td></tr><tr><td style="text-align:left;"><strong>Виконання</strong></td><td style="text-align:left;">Негайно</td><td style="text-align:left;">Одразу після завантаження</td><td style="text-align:left;">Після парсингу всього HTML</td></tr><tr><td style="text-align:left;"><strong>Зберігає порядок?</strong></td><td style="text-align:left;">Так</td><td style="text-align:left;">Ні</td><td style="text-align:left;">Так</td></tr><tr><td style="text-align:left;"><strong>Блокує рендеринг?</strong></td><td style="text-align:left;">Так</td><td style="text-align:left;">Під час виконання</td><td style="text-align:left;">Ні</td></tr></tbody></table><p><strong>Золоте правило:</strong> Використовуйте defer для ваших основних скриптів, щоб сторінка вантажилася швидко, а DOM був доступний. Використовуйте async лише для сторонніх метрик та аналітики.</p><h2 id="де-в-html-підключати-async-та-defer" tabindex="-1"><strong>Де в HTML підключати async та defer?</strong> <a class="header-anchor" href="#де-в-html-підключати-async-та-defer" aria-label="Permalink to &quot;**Де в HTML підключати async та defer?**&quot;">​</a></h2><p>Сучасний стандарт (Best Practice) — розміщувати скрипти з атрибутами async та defer всередині тегу <code>&lt;head&gt;</code>.</p><h3 id="чому-саме-в-head-а-не-в-кінці-body" tabindex="-1"><strong>Чому саме в &lt;head&gt;, а не в кінці &lt;body&gt;?</strong> <a class="header-anchor" href="#чому-саме-в-head-а-не-в-кінці-body" aria-label="Permalink to &quot;**Чому саме в \\&lt;head\\&gt;, а не в кінці \\&lt;body\\&gt;?**&quot;">​</a></h3><blockquote><ul><li><strong>Раннє виявлення та завантаження:</strong> Коли браузер починає читати HTML-документ зверху вниз, він одразу бачить тег <code>&lt;script&gt;</code> у <code>&lt;head&gt;</code> і починає завантажувати файл по мережі. Оскільки атрибути async та defer дозволяють фонове (паралельне) завантаження, браузер продовжує малювати сторінку, поки скрипт «качається».</li><li><strong>Що буде, якщо помістити перед</strong> <code>&lt;/body&gt;</code><strong>:</strong> Браузер дізнається про існування скрипта лише тоді, коли прочитає весь HTML (відобразить майже всю сторінку). Завантаження скрипта почнеться із великим запізненням. Це повністю нівелює головну перевагу цих атрибутів — можливість завантажувати скрипт і парсити HTML одночасно.</li></ul></blockquote><h3 id="як-розташування-впливає-на-логіку-виконання" tabindex="-1"><strong>Як розташування впливає на логіку виконання?</strong> <a class="header-anchor" href="#як-розташування-впливає-на-логіку-виконання" aria-label="Permalink to &quot;**Як розташування впливає на логіку виконання?**&quot;">​</a></h3><blockquote><ul><li><strong>Для defer:</strong> Незалежно від того, де він розташований, його виконання відкладається до моменту, коли весь HTML буде повністю розібраний. Але розташування у <code>&lt;head&gt;</code> гарантує, що до моменту закінчення парсингу HTML скрипт уже буде завантажений і готовий до миттєвого виконання.</li><li><strong>Для async:</strong> Скрипт виконується одразу після того, як повністю завантажений. Якщо він знаходиться в <code>&lt;head&gt;</code>, завантаження почнеться раніше, і він виконається раніше. Якщо в кінці &lt;body&gt; — завантаження почнеться пізно, відповідно і виконання відкладеться.</li></ul></blockquote><h3 id="короткии-підсумок" tabindex="-1"><strong>Короткий підсумок</strong> <a class="header-anchor" href="#короткии-підсумок" aria-label="Permalink to &quot;**Короткий підсумок**&quot;">​</a></h3><blockquote><ul><li>Якщо ви використовуєте <strong>звичайний</strong> <code>&lt;script&gt;</code> (без атрибутів), його потрібно ставити перед закриваючим <code>&lt;/body&gt;</code>, щоб уникнути довгого завантаження (білого екрану).</li><li>Якщо ви використовуєте <code>&lt;script defer&gt;</code> <strong>або</strong> <code>&lt;script async&gt;</code>, їхнє законне місце — у <code>&lt;head&gt;</code>, щоб браузер почав їхнє завантаження якомога раніше.</li></ul></blockquote></div>',2)])])}const y=e(o,[["render",s]]);export{f as __pageData,y as default};
